func stateLabel(s string) string {
	switch s {
	case "success":
		return "success"
	case "failed":
		return "failed"
	case "running":
		return "running"
	case "queued":
		return "queued"
	case "retrying":
		return "retrying"
	case "canceled":
		return "canceled"
	case "pending":
		return "pending"
	case "skipped":
		return "skipped"
	case "":
		return "never ran"
	}
	return s
}

// stateText is a state's word colour.
func stateText(s string) string {
	switch s {
	case "success", "failed", "running", "queued", "retrying", "canceled", "skipped":
		return "text-state-" + s
	}
	return "text-muted"
}

func stateClass(s string) string {
	switch s {
	case "success":
		return "bg-state-success/13 text-state-success"
	case "failed":
		return "bg-state-failed/13 text-state-failed"
	case "running":
		return "bg-state-running/13 text-state-running"
	case "queued":
		return "bg-state-queued/13 text-state-queued"
	case "retrying":
		return "bg-state-retrying/13 text-state-retrying"
	case "canceled":
		return "bg-state-canceled/13 text-state-canceled"
	case "skipped":
		return "bg-state-skipped/13 text-state-skipped"
	}
	return "bg-surface-2 text-muted"
}

// StateFill is a state's colour as a fill, without the pulse a dot has: a
// strip of squares where every running one blinked would be noise.
func StateFill(s string) string {
	return strings.TrimSuffix(stateDot(s), " animate-pulse")
}

func stateDot(s string) string {
	switch s {
	case "success":
		return "bg-state-success"
	case "failed":
		return "bg-state-failed"
	case "running":
		return "bg-state-running animate-pulse"
	case "queued":
		return "bg-state-queued"
	case "retrying":
		return "bg-state-retrying animate-pulse"
	case "canceled":
		return "bg-state-canceled"
	case "skipped":
		return "bg-state-skipped"
	}
	return "bg-state-pending"
}

